arguments.old:
lo, hi = 0, len(sorted_list) - 1
while lo <= hi:
    mid = (lo + hi) // 2
    if sorted_list[mid] == target:
        return mid
    if sorted_list[mid] < target:
        lo = mid + 1
    else:
        hi = mid - 1
return -1

arguments.new:
# Find the insertion point to the left of every value equal to target.
# Using a half-open interval means that a match does not terminate the
# search: there may still be an earlier occurrence.
lo, hi = 0, len(sorted_list)
while lo < hi:
    mid = (lo + hi) // 2
    if sorted_list[mid] < target:
        lo = mid + 1
    else:
        hi = mid

if lo < len(sorted_list) and sorted_list[lo] == target:
    return lo
return -1
